/// <summary>
///     The <c>AVACustInvoiceTransDbt_Extension</c> class is the extension for <c>CustInvoiceTrans</c>
/// </summary>
[ExtensionOf(tableStr(CustInvoiceTrans))]
final class AVACustInvoiceTransDbt_Extension
{
}

Method.Source:
    /// <summary>
///    AVA <c>initFromSalesLine</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
/// <param name="_salesParmLine">
///    <c>SalesParmLine</c> as type
/// </param>
public void initFromSalesLine(  SalesLine       _salesLine,
                                SalesParmLine   _salesParmLine)
{
    #xppTexts
    InventTable avaInventTable = _salesLine.inventTable();
    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(avaInventTable.Product, _salesLine.salesTable().LanguageId);

    next initFromSalesLine(_salesLine, _salesParmLine);

    this.AVAPriceSurchargeCode          = _salesLine.AVAPriceSurchargeCode;
    this.AVAPriceSurchargePercentage    = _salesLine.AVAPriceSurchargePercentage;
    this.AVAQuotationId                 = _salesLine.AVAQuotationId;
    this.AVAPreferenceAuthorized        = _salesLine.NDX_PreferenceAuthorized;

    if(avaProductTranslation)
    {
        this.Name                       = avaProductTranslation.NDXProductName1 + #newLine + avaProductTranslation.NDXProductName2;
    }

    if(_salesLine.salesTable().NDX_ItemNameVersionReport == NDX_ItemNameVersionReport::LongText
        || _salesLine.AVAOverwriteText == NoYes::Yes)
    {
        this.Name                       += #newLine + _salesLine.Name;
    }    
}

/// <summary>
///    AVA <c>displayAVAQtyCreditNoteReturnOrder</c> method.
/// </summary>
/// <returns>
///    <c>AVAQtyCreditNoteReturnOrder</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display AVAQtyCreditNoteReturnOrder displayAVAQtyCreditNoteReturnOrder()
{
    AVAQtyCreditNoteReturnOrder retVal;

    SalesLine                   locSalesLine;

    locSalesLine = this.salesLine();

    if(locSalesLine.RecId)
    {
        retVal = locSalesLine.displayAVAQtyCreditNoteReturnOrder();
    }

    return retVal;
}

/// <summary>
/// returns the associated CustPackingSlipJour record
/// </summary>
/// <returns>CustPackingSlipJour</returns>
public CustPackingSlipJour avaLastPackingSlipJour()
{
    CustPackingSlipJour locCustPackingSlipJour;
    container avaPackingSlipCon = this.packingSlipIdAndDate(this.custInvoiceJour());

    if(conPeek(avaPackingSlipCon, 2) != '*'
        && conPeek(avaPackingSlipCon, 2) != '')
    {
        select firstonly locCustPackingSlipJour
            where locCustPackingSlipJour.PackingSlipId == conPeek(avaPackingSlipCon, 2)
                && locCustPackingSlipJour.DeliveryDate == conPeek(avaPackingSlipCon, 3);
    }

    return locCustPackingSlipJour;
}
